private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        return i;
    }
    int remaining = bb.remaining();
    while (i < remaining) {
        int b1 = bb.get(i) & 0xFF;
        int codePoint;
        int nextIndex;

        if (b1 < 0x80) {
            // Single byte (ASCII)
            codePoint = b1;
            nextIndex = i + 1;
        } else if ((b1 & 0xE0) == 0xC0) {
            // Two bytes
            if (i + 1 >= remaining) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b2 = bb.get(i + 1) & 0xFF;
            if ((b2 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            }
            codePoint = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
            if (codePoint < 0x80) {
                throw new IllegalArgumentException("Overlong UTF-8 sequence");
            }
            nextIndex = i + 2;
        } else if ((b1 & 0xF0) == 0xE0) {
            // Three bytes
            if (i + 2 >= remaining) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b2 = bb.get(i + 1) & 0xFF;
            int b3 = bb.get(i + 2) & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            }
            codePoint = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            if (codePoint < 0x800) {
                throw new IllegalArgumentException("Overlong UTF-8 sequence");
            }
            if (codePoint >= 0xD800 && codePoint <= 0xDFFF) {
                throw new IllegalArgumentException("Surrogate character not allowed in UTF-8");
            }
            nextIndex = i + 3;
        } else if ((b1 & 0xF8) == 0xF0) {
            // Four bytes
            if (i + 3 >= remaining) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b2 = bb.get(i + 1) & 0xFF;
            int b3 = bb.get(i + 2) & 0xFF;
            int b4 = bb.get(i + 3) & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            }
            codePoint = ((b1 & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            if (codePoint < 0x10000) {
                throw new IllegalArgumentException("Overlong UTF-8 sequence");
            }
            if (codePoint > 0x10FFFF) {
                throw new IllegalArgumentException("Code point out of range");
            }
            nextIndex = i + 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 start byte");
        }

        sb.appendCodePoint(codePoint);
        i = nextIndex;
    }
    return i;
}

