public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hashCode = 1;
    for (long l : array) {
        int k = (int) (l ^ (l >>> 32));
        hashCode = 31 * hashCode + k;
    }
    return hashCode;
}

