public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }

    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Class<?> rawType = (Class<?>) parameterizedType.getRawType();

    if (!targetType.equals(rawType) && !targetType.isAssignableFrom(rawType)) {
        return null;
    }

    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArgs = new Class<?>[actualTypeArguments.length];
    boolean allResolved = true;

    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArg = actualTypeArguments[i];
        if (typeArg instanceof Class) {
            resolvedArgs[i] = (Class<?>) typeArg;
        } else if (typeArg instanceof ParameterizedType) {
            // For nested parameterized types, we need the raw class
            ParameterizedType nestedType = (ParameterizedType) typeArg;
            if (nestedType.getRawType() instanceof Class) {
                resolvedArgs[i] = (Class<?>) nestedType.getRawType();
            } else {
                allResolved = false;
                break;
            }
        } else {
            // Wildcard types or type variables and other non-class types
            allResolved = false;
            break;
        }
    }

    if (allResolved) {
        return resolvedArgs;
    }

    return null;
}

