public void put(LoggingEvent o) {
    if (o == null) {
        return;
    }

    // If the buffer is full, we can check if the given event is more important than the oldest event
    // in the buffer based on its "chance of being logged" (getLevel). If it is, we remove the oldest
    // event and add the new one; otherwise, it is silently dropped.

    if (isFull()) {
        // Obtain the oldest event from the buffer.
        LoggingEvent oldest = peek();

        // If the new event has a higher logging level (more important), replace the oldest.
        if (oldest == null || o.getLevel().isGreaterOrEqual(oldest.getLevel())) {
            // Remove the oldest event to make space.
            remove();
            // Add the new event.
            f.add(o);
        } else {
            // Silently drop the new event.
            return;
        }
    } else {
        // Buffer has space, just add the new event.
        f.add(o);
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
