static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    // Extract year, month, day from timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Check month and day validity
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month: " + month);
    }
    // Determine days in month
    int daysInMonth;
    switch (month) {
        case 2:
            daysInMonth = isLeapYear(year) ? 29 : 28;
            break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30;
            break;
        default:
            daysInMonth = 31;
            break;
    }
    if (day < 1 || day > daysInMonth) {
        throw new IllegalArgumentException("Invalid day: " + day + " for month " + month + " in year " + year);
    }

    // Calculate the first day of the current bucket
    // The bucket is determined by dayStep from the beginning of the month
    int firstDayOfBucket = ((day - 1) / dayStep) * dayStep + 1;

    // If the computed firstDayOfBucket exceeds the days in the month, it may need adjustment
    // But typically dayStep is small so this shouldn't be an issue. Still, let's handle gracefully.

    return year * 10000L + month * 100L + firstDayOfBucket;
}

