                String key = entry.getKey();
                JsonElement element = entry.getValue();

                Map<String, Object> atsMap = new HashMap<>();
                atsMap.put("type", key);

                if (element.isJsonArray()) {
                    List<Object> atsDetails = new ArrayList<>();
                    for (JsonElement detail : element.getAsJsonArray()) {
                        if (detail.isJsonObject()) {
                            Map<String, Object> detailMap = new HashMap<>();
                            Iterator<Entry<String, JsonElement>> detailIterator = detail.getAsJsonObject().entrySet().iterator();
                            while (detailIterator.hasNext()) {
                                Entry<String, JsonElement> detailEntry = detailIterator.next();
                                detailMap.put(detailEntry.getKey(), detailEntry.getValue().getAsString());
                            }
                            atsDetails.add(detailMap);
                        } else {
                            atsDetails.add(detail.getAsString());
                        }
                    }
                    atsMap.put("details", atsDetails);
                } else {
                    atsMap.put("value", element.getAsString());
                }

                atsList.add(atsMap);
            }
            content.put("ats", atsList);
        }
    }

