private void moveAllListNodes(DoublyLinkedList<E> list) {
        if (list == this) {
            throw new IllegalArgumentException("list may not be this list");
        }
        ListNode<E> node = list.head;
        if (node != null) {
            list.head = null;
            list.tail = null;
            list.size = 0;

            node.next = null;
            node.prev = tail;
            if (tail == null) {
                head = node;
            } else {
                tail.next = node;
            }
            tail = node;

            node = list.head;
            if (node == null) {
                return;
            }
        }
        this.size += list.size;
        list.size = 0;

        while (node != null) {
            ListNode<E> next = node.next;
            node.next = tail;
            node.prev = tail.prev;
            if (tail.prev == null) {
                head = node;
            } else {
                tail.prev.next = node;
            }
            tail.prev = node;
            tail = node;
            node = next;
        }
    }

