private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();

    for (E e : this.edges()) {
        Integer tail = this.tail(e);
        Integer head = this.head(e);

        // Get neighbors of tail and head vertices
        Collection<Integer> tailNeighbors = this.tail(e) != null ? this.nodeTailMap().get(tail) : null;
        Collection<Integer> headNeighbors = this.head(e) != null ? this.nodeHeadMap().get(head) : null;

        if (tailNeighbors == null || headNeighbors == null) {
            continue;
        }

        List<Pair<Integer, Integer>> separator = extractMinimalSeparator(tail, head, tailNeighbors, headNeighbors);

        if (separator != null && !separator.isEmpty()) {
            separatorList.add(new Pair<>(separator, e));
        }
    }

    return separatorList;
}

