private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (vertices.isEmpty()) {
        return true;
    }
    for (V v : vertices) {
        for (V u : vertices) {
            if (v.equals(u)) {
                continue;
            }
            if (!graph.containsEdge(v, u)) {
                return false;
            }
        }
    }
    return true;
}

