    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        return;
    }
    // If the descriptor is a method descriptor, it starts with '(' and ends with ')'
    if (descriptor.startsWith("(") && descriptor.endsWith(")")) {
        String argTypes = descriptor.substring(1, descriptor.length() - 1);
        int index = 0;
        while (index < argTypes.length()) {
            char c = argTypes.charAt(index);
            switch (c) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'J': // long
                case 'S': // short
                case 'Z': // boolean
                    index++;
                    // For each primitive type, we need to pop from the stack
                    // but since this is about abstract types, we assume we're tracking the count or some representation
                    // For this implementation, we'll just simulate the pop by moving the index
                    // In a real scenario, you'd call outputFrame.pop() for each type
                    // Here, we'll just update the index to simulate the pop operation
                    break;
                case '[': // array
                    // Array types: keep reading until we find the component type
                    index++;
                    break;
                case 'L': // class
                    // Class types end with ';'
                    int end = argTypes.indexOf(';', index);
                    if (end == -1) {
                        // Malformed descriptor, stop processing
                        return;
                    }
                    index = end + 1;
                    break;
                default:
                    // Unknown type, stop processing
                    return;
            }
        }
    } else {
        // If it's a type descriptor, just pop according to that type
        // Similar logic as above but for a single type
        int index = 0;
        while (index < descriptor.length()) {
            char c = descriptor.charAt(index);
            switch (c) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'J': // long
                case 'S': // short
                case 'Z': // boolean
                    index++;
                    break;
                case '[': // array
                    index++;
                    break;
                case 'L': // class
                    int end = descriptor.indexOf(';', index);
                    if (end == -1) {
                        return;
                    }
                    index = end + 1;
                    break;
                default:
                    return;
            }
        }
    }
}

