public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath cannot be null");
    }

    // Normalize the path to use "/" separators
    String normalizedPath = path.replace('\\', '/');
    String normalizedRelativePath = relativePath.replace('\\', '/');

    // If the relative path is absolute, return it as is (normalized)
    if (normalizedRelativePath.startsWith("/")) {
        return normalizedRelativePath;
    }

    // If the base path ends with '/', remove the trailing slash to avoid double slashes
    if (normalizedPath.endsWith("/") && normalizedPath.length() > 1) {
        normalizedPath = normalizedPath.substring(0, normalizedPath.length() - 1);
    }

    // Combine the paths
    String fullPath;
    if (normalizedRelativePath.isEmpty()) {
        fullPath = normalizedPath;
    } else {
        fullPath = normalizedPath + "/" + normalizedRelativePath;
    }

    // Resolve path segments (handle ".." and ".")
    String[] segments = fullPath.split("/");
    Deque<String> resolvedSegments = new ArrayDeque<>();

    for (String segment : segments) {
        if (segment.isEmpty() || ".".equals(segment)) {
            continue;
        } else if ("..".equals(segment)) {
            if (!resolvedSegments.isEmpty()) {
                resolvedSegments.removeLast();
            }
            // If we're at the root and still have "..", we stay at root (or handle as needed)
            // Standard behavior: ".." at root stays at root
        } else {
            resolvedSegments.addLast(segment);
        }
    }

    // Check if the original path was absolute (started with /)
    boolean isAbsolutePath = normalizedPath.startsWith("/") || normalizedRelativePath.startsWith("/");

    // Build the result
    StringBuilder result = new StringBuilder();
    if (isAbsolutePath) {
        result.append('/');
    }

    boolean first = true;
    for (String segment : resolvedSegments) {
        if (!first) {
            result.append('/');
        }
        result.append(segment);
        first = false;
    }

    // If the original relative path ended with a slash, we should consider that
    // But typically path resolution doesn't preserve trailing slashes unless specified
    // Let's check if the path was empty and should be root
    if (result.length() == 0) {
        return isAbsolutePath ? "/" : ".";
    }

    return result.toString();
}

