static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return new String[0];
    }
    int nullCount = 0;
    for (Object obj : array) {
        if (obj == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        // No null elements, but we still need to ensure all elements are Strings
        // Check if all elements are Strings
        boolean allStrings = true;
        for (Object obj : array) {
            if (obj != null && !(obj instanceof String)) {
                allStrings = false;
                break;
            }
        }
        if (allStrings) {
            // Cast is safe
            @SuppressWarnings("unchecked")
            String[] result = (String[]) array.clone();
            return result;
        }
    }
    // Create new array without nulls
    int size = array.length - nullCount;
    String[] result = new String[size];
    int index = 0;
    for (Object obj : array) {
        if (obj != null) {
            // Convert to String if needed
            if (obj instanceof String) {
                result[index++] = (String) obj;
            } else {
                result[index++] = obj.toString();
            }
        }
    }
    return result;
}

